import{_ as l,a0 as o,w as p,s as u,I as n,x as s,a1 as e,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"使用 Quagga 實現 Linux 動態路由 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Quagga 實現 Linux 動態路由 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Quagga 實現 Linux 動態路由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Quagga 實現 Linux 動態路由 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180308 Dynamic Linux Routing with Quagga","title":"使用 Quagga 實現 Linux 動態路由","tag":"201806","desc":""},"relativePath":"201806/20180308 Dynamic Linux Routing with Quagga.md","filePath":"[post].md"}'),r={name:"201806/20180308 Dynamic Linux Routing with Quagga.md"};function g(f,a,b,c,h,k){const t=o("Link");return p(),u("div",null,[a[24]||(a[24]=n("h1",{id:"使用-quagga-實現-linux-動態路由",tabindex:"-1"},[s("使用 Quagga 實現 Linux 動態路由 "),n("a",{class:"header-anchor",href:"#使用-quagga-實現-linux-動態路由","aria-label":"Permalink to “使用 Quagga 實現 Linux 動態路由”"},"​")],-1)),a[25]||(a[25]=n("blockquote",null,[n("p",null,"學習如何使用 Quagga 套件的路由協議去管理動態路由。")],-1)),a[26]||(a[26]=n("p",null,[n("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/network_visualization.png?itok=P3Ve7eO1",alt:"network",title:"network"})],-1)),n("p",null,[a[2]||(a[2]=s("迄今為止，本系列文章中，我們已經在 ",-1)),e(t,{href:"https://linux.cn/article-9657-1.html"},{default:i(()=>[...a[0]||(a[0]=[s("Linux 局域網路由新手指南：第 1 部分",-1)])]),_:1}),a[3]||(a[3]=s(" 中學習了複雜的 IPv4 地址，在  ",-1)),e(t,{href:"https://linux.cn/article-9675-1.html"},{default:i(()=>[...a[1]||(a[1]=[s("Linux 局域網路由新手指南：第 2 部分",-1)])]),_:1}),a[4]||(a[4]=s(" 中學習瞭如何去手工創建靜態路由。",-1))]),n("p",null,[a[6]||(a[6]=s("今天，我們繼續使用 ",-1)),e(t,{href:"https://www.quagga.net/"},{default:i(()=>[...a[5]||(a[5]=[s("Quagga",-1)])]),_:1}),a[7]||(a[7]=s(" 去管理動態路由，這是一個安裝完後就不用理它的的軟件。Quagga 是一個支持 OSPFv2、OSPFv3、RIP v1 和 v2、RIPng、以及 BGP-4 的路由協議套件，並全部由 zebra 守護程序管理。",-1))]),a[27]||(a[27]=d(`<p>OSPF 的意思是<ruby>最短路徑優先<rt>Open Shortest Path First</rt></ruby>。OSPF 是一個內部網關協議（IGP）;它可以用在局域網和跨因特網的局域網互聯中。在你的網絡中的每個 OSPF 路由器都包含整個網絡的拓撲，並計算通過該網絡的最短路徑。OSPF 會通過多播的方式自動對外傳播它檢測到的網絡變化。你可以將你的網絡分割為區域，以保持路由表的可管理性；每個區域的路由器只需要知道離開它的區域的下一跳接口地址，而不用記錄你的網絡的整個路由表。</p><p>RIP，即路由信息協議，是一個很老的協議，RIP 路由器向網絡中週期性多播它的整個路由表，而不是像 OSPF 那樣只多播網絡的變化。RIP 通過跳數來測量路由，任何超過 15 跳的路由它均視為不可到達。RIP 設置很簡單，但是 OSPF 在速度、效率以及彈性方面更佳。</p><p>BGP-4 是邊界網關協議版本 4。這是用於因特網流量路由的外部網關協議（EGP）。你不會用到 BGP 協議的，除非你是因特網服務提供商。</p><h3 id="準備使用-ospf" tabindex="-1">準備使用 OSPF <a class="header-anchor" href="#準備使用-ospf" aria-label="Permalink to “準備使用 OSPF”">​</a></h3><p>在我們的小型 KVM 測試實驗室中，用兩台虛擬機表示兩個不同的網絡，然後將另一台虛擬機配置為路由器。創建兩個網絡：net1 是 192.168.110.0/24 ，而 net2 是 192.168.120.0/24。啓用 DHCP 是明智的，否則你要分別進入這三個虛擬機，去為它們設置靜態地址。Host 1 在 net1 中，Host 2 在 net2 中，而路由器同時與這兩個網絡連接。設置 Host 1 的網關地址為 192.168.110.126，Host 2 的網關地址為 192.168.120.136。</p><ul><li>Host 1： 192.168.110.125</li><li>Host 2：192.168.120.135</li><li>Router：192.168.110.126 和 192.168.120.136</li></ul><p>在路由器上安裝 Quagga。在大多數 Linux 中它是 quagga 軟件包。在 Debian 上還有一個單獨的文檔包 quagga-doc。取消 <code>/etc/sysctl.conf</code> 配置文件中如下這一行的註釋去啓用包轉發功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>net.ipv4.ip_forward=1</span></span></code></pre></div><p>然後，運行 <code>sysctl -p</code> 命令讓變化生效。</p><h3 id="配置-quagga" tabindex="-1">配置 Quagga <a class="header-anchor" href="#配置-quagga" aria-label="Permalink to “配置 Quagga”">​</a></h3><p>查看你的 Quagga 包中的示例配置文件，比如，<code>/usr/share/doc/quagga/examples/ospfd.conf.sample</code>。除非你的 Linux 版本按你的喜好做了創新，否則，一般情況下配置文件應該在 <code>/etc/quagga</code> 目錄中。大多數 Linux 版本在這個目錄下有兩個文件，<code>vtysh.conf</code>  和 <code>zebra.conf</code>。它們提供了守護程序運行所需要的最小配置。除非你的發行版做了一些特殊的配置，否則，zebra 總是首先運行，當你啓動 ospfd 的時候，它將自動啓動。Debian/Ubuntu 是一個特例，稍後我們將會説到它。</p><p>每個路由器守護程序將讀取它自己的配置文件，因此，我們必須創建 <code>/etc/quagga/ospfd.conf</code>，並輸入如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>!/etc/quagga/ospfd.conf</span></span>
<span class="line"><span>hostname router1</span></span>
<span class="line"><span>log file /var/log/quagga/ospfd.log</span></span>
<span class="line"><span>router ospf</span></span>
<span class="line"><span>  ospf router-id 192.168.110.15</span></span>
<span class="line"><span>  network 192.168.110.0/0 area 0.0.0.0</span></span>
<span class="line"><span>  network 192.168.120.0/0 area 0.0.0.0</span></span>
<span class="line"><span>access-list localhost permit 127.0.0.1/32</span></span>
<span class="line"><span>access-list localhost deny any</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span>  access-class localhost</span></span></code></pre></div><p>你可以使用感嘆號（<code>!</code>）或者井號（<code>#</code>）去註釋掉這些行。我們來快速瀏覽一下這些選項。</p><ul><li><code>hostname</code> 可以是你希望的任何內容。這裏不是一般意義上的 Linux 主機名，但是，當你使用 <code>vtysh</code> 或者 <code>telnet</code> 登入時，你將看到它們。</li><li><code>log file</code> 是你希望用於保存日誌的任意文件。</li><li><code>router</code> 指定路由協議。</li><li><code>ospf router-id</code> 是任意的 32 位數字。使用路由器的一個 IP 地址就是很好的選擇。</li><li><code>network</code> 定義你的路由器要通告的網絡。</li><li><code>access-list</code> 限制 <code>vtysh</code> 登入，它是 Quagga 命令列 shell，它允許本地機器登入，並拒絕任何遠程管理。</li></ul><h3 id="debian-ubuntu" tabindex="-1">Debian/Ubuntu <a class="header-anchor" href="#debian-ubuntu" aria-label="Permalink to “Debian/Ubuntu”">​</a></h3><p>在你啓動守護程序之前，Debian/Ubuntu 相對其它的 Debian 衍生版可能多需要一步到多步。編輯 <code>/etc/quagga/daemons</code> ，除了 <code>zebra=yes</code> 和 <code>ospfd=yes</code> 外，使其它所有的行的值為 <code>no</code>。</p><p>然後，在 Debian 上運行 <code>ospfd</code> 去啓動 Quagga：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start quagga</span></span></code></pre></div><p>在大多數的其它 Linux 上，包括 Fedora 和 openSUSE，用如下命令啓動 <code>ospfd</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start ospfd</span></span></code></pre></div><p>現在，Host 1 和 Host 2 將可以互相 ping 通對方和路由器。</p><p>這裏用了許多篇幅去描述非常簡單的設置。在現實中，路由器將連接兩個交換機，然後為連接到這個交換機上的所有電腦提供一個網關。你也可以在你的路由器上添加更多的網絡接口，這樣你的路由器就可以為更多的網絡提供路由服務，或者也可以直接連接到其它路由器上，或者連接到連接其它路由器的骨幹網絡上。</p><p>你或許不願意如此麻煩地手工配置網絡接口。最簡單的方法是使用你的 DHCP 服務器去宣告你的路由器。如果你使用了 Dnsmasq，那麼你就有了一個 DHCP 和 DNS 的一體化解決方案。</p>`,24)),n("p",null,[a[9]||(a[9]=s("還有更多的配置選項，比如，加密的密碼保護。更多內容請查看 ",-1)),e(t,{href:"https://www.quagga.net/"},{default:i(()=>[...a[8]||(a[8]=[s("Quagga 路由套件",-1)])]),_:1}),a[10]||(a[10]=s(" 的官方文檔。",-1))]),a[28]||(a[28]=n("hr",null,null,-1)),n("p",null,[a[12]||(a[12]=s("via: ",-1)),e(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/3/dynamic-linux-routing-quagga"},{default:i(()=>[...a[11]||(a[11]=[s("https://www.linux.com/learn/intro-to-linux/2018/3/dynamic-linux-routing-quagga",-1)])]),_:1})]),n("p",null,[a[16]||(a[16]=s("作者：",-1)),e(t,{href:"https://www.linux.com/users/cschroder"},{default:i(()=>[...a[13]||(a[13]=[s("CARLA SCHRODER",-1)])]),_:1}),a[17]||(a[17]=s(" 譯者：",-1)),e(t,{href:"https://github.com/qhwdw"},{default:i(()=>[...a[14]||(a[14]=[s("qhwdw",-1)])]),_:1}),a[18]||(a[18]=s(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[15]||(a[15]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[21]||(a[21]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...a[20]||(a[20]=[s("Linux中國",-1)])]),_:1}),a[23]||(a[23]=s(" 榮譽推出",-1))])])}const P=l(r,[["render",g]]);export{w as __pageData,P as default};
